ng: Shaping beards to face shape."], ["Hot towel shave","Trade term \u2014 Hot towel shave: Classic straight-razor shave with hot towels."], ["Straight razor","Trade term \u2014 Straight razor: The classic folding shave blade."], ["Shavette","Trade term \u2014 Shavette: Straight razor using disposable blades."], ["Guard numbers","Trade term \u2014 Guard numbers: Clipper guard lengths: #1 is 1/8 inch, etc."], ["Blend","Trade term \u2014 Blend: Seamless transition between lengths."], ["Texture","Trade term \u2014 Texture: Thinning or point-cutting for movement."], ["Crown","Trade term \u2014 Crown: The swirl at the back of the head; cut with the grain."], ["Nape","Trade term \u2014 Nape: The neckline; tapered or blocked."], ["Sideburn","Trade term \u2014 Sideburn: Shaped to complement the cut."], ["Barbicide","Trade term \u2014 Barbicide: The blue disinfectant of barbershops."], ["Booth rental","Trade term \u2014 Booth rental: Renting a chair in a shop as an independent barber."], ["Book","Trade term \u2014 Book: A barber's regular client list."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
console.log("== drill ==");console.log(ask(5));

